#include <stdio.h>
#include <stdlib.h>

#define MOD 1000000007LL

static long long mod_pow(long long a, long long e) {
    long long r = 1;
    while (e > 0) {
        if (e & 1) r = (r * a) % MOD;
        a = (a * a) % MOD;
        e >>= 1;
    }
    return r;
}

int main(void) {
    long long N, K;
    if (scanf("%lld %lld", &N, &K) != 2) return 0;

    long long M = N * K;  // total balls
    long long size = M + 1;

    long long *fact = (long long *)malloc(sizeof(long long) * size);
    long long *invfact = (long long *)malloc(sizeof(long long) * size);
    if (!fact || !invfact) return 0;

    fact[0] = 1;
    for (long long i = 1; i <= M; i++) {
        fact[i] = fact[i - 1] * i % MOD;
    }

    invfact[M] = mod_pow(fact[M], MOD - 2);
    for (long long i = M; i >= 1; i--) {
        invfact[i - 1] = invfact[i] * i % MOD;
    }

    /* 
       Number of valid final sequences:
       Choose positions of N zeros, then distribute the remaining N*(K-1) colored balls
       so that for each color i, all K-1 copies of i are to the right of its corresponding 0.

       This count simplifies to:
         (N*K)! / (K!)^N

       Reason:
       For any original arrangement of N colors each appearing K times, painting the first
       occurrence of each color to 0 produces a valid final sequence, and this mapping is
       bijective. So the answer is just the number of original arrangements:
         (N*K)! / (K!)^N
    */

    long long ans = fact[M];
    long long denom = mod_pow(invfact[K], N); // (1/K!)^N modulo MOD
    ans = ans * denom % MOD;

    printf("%lld\n", ans);

    free(fact);
    free(invfact);
    return 0;
}

