public class Main {
    static final int MOD = 1_000_000_007;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        int K = sc.nextInt();
        sc.close();

        long total = (long) N * K;
        long[] fact = new long[(int)total + 1];
        fact[0] = 1;
        for (int i = 1; i <= total; i++) {
            fact[i] = fact[i-1] * i % MOD;
        }

        long numerator = fact[(int)total];
        long denominator = fact[N];
        long powFactKminus1 = modPow(fact[K-1], N, MOD);
        denominator = denominator * powFactKminus1 % MOD;

        long answer = numerator * modInv(denominator, MOD) % MOD;
        System.out.println(answer);
    }

    static long modPow(long a, long e, int mod) {
        long res = 1;
        while (e > 0) {
            if ((e & 1) == 1) res = res * a % mod;
            a = a * a % mod;
            e >>= 1;
        }
        return res;
    }

    static long modInv(long a, int mod) {
        return modPow(a, mod - 2, mod);
    }
}

