public class Main {
    static final long MOD = 1_000_000_007L;

    static long modPow(long a, long e) {
        long r = 1;
        while (e > 0) {
            if ((e & 1) == 1) r = r * a % MOD;
            a = a * a % MOD;
            e >>= 1;
        }
        return r;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int N = fs.nextInt();
        int K = fs.nextInt();

        int max = N * K;
        long[] fact = new long[max + 1];
        long[] invFact = new long[max + 1];
        fact[0] = 1;
        for (int i = 1; i <= max; i++) fact[i] = fact[i - 1] * i % MOD;
        invFact[max] = modPow(fact[max], MOD - 2);
        for (int i = max; i >= 1; i--) invFact[i - 1] = invFact[i] * i % MOD;

        // Number of valid resulting sequences:
        // (NK)! / (K-1)!^N * product_{i=0}^{N-1} 1 / (iK + 1)
        long ans = fact[max];
        long denom = 1;

        long km1Fact = fact[K - 1];
        for (int i = 0; i < N; i++) {
            denom = denom * km1Fact % MOD;
            denom = denom * (1L * i * K + 1) % MOD;
        }

        ans = ans * modPow(denom, MOD - 2) % MOD;
        System.out.println(ans);
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ');

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }
}

