#include <bits/stdc++.h>
using namespace std;

static const long long MOD = 1000000007LL;

long long modpow(long long a, long long e) {
    long long r = 1 % MOD;
    while (e > 0) {
        if (e & 1) r = r * a % MOD;
        a = a * a % MOD;
        e >>= 1;
    }
    return r;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long N, K;
    cin >> N >> K;

    // Number of valid final sequences:
    // N! * ((N*K - N)! / ((K-1)!)^N)
    //
    // Reason:
    // Choose positions of the N zeros and assign which original color each zero
    // corresponds to. In the final sequence, for each color i (1..N), all its
    // K-1 remaining balls must appear only after its corresponding zero.
    //
    // Equivalently, arrange N distinct zeros and N groups of K-1 identical balls
    // with the precedence constraint "zero_i before all balls of color i".
    // Counting gives:
    //   (N*K)! / (K!)^N
    // which is algebraically equal to
    //   N! * (N*K - N)! / ((K-1)!)^N

    long long M = N * K;

    vector<long long> fact(M + 1), invfact(M + 1);
    fact[0] = 1;
    for (long long i = 1; i <= M; i++) fact[i] = fact[i - 1] * i % MOD;

    invfact[M] = modpow(fact[M], MOD - 2);
    for (long long i = M; i >= 1; i--) invfact[i - 1] = invfact[i] * i % MOD;

    long long ans = fact[M];
    long long invKfact = invfact[K];
    for (long long i = 0; i < N; i++) {
        ans = ans * invKfact % MOD;
    }

    cout << ans % MOD << '\n';
    return 0;
}
